import React from 'react';
import { ColumnInstance } from 'react-table';

/**
 * This function gets the best fit alignment for the column/cell action
 * menu. It takes into consideration the column alignment and also width
 * of the column compared to the width of the table to make sure the menu
 * does not end up outside the table width.
 *
 * @param tableContainerRef - virtual container ref of the table
 * @param buttonRef - the trigger button ref to figure relative positioning of button and table
 * @param column - column to which the cell or header belongs to
 *
 * @returns alignment in terms of 'center' | 'end' | 'start' for our dropdown menu alignment.
 */
export function useActionsMenuAlignment(
  tableContainerRef: React.RefObject<HTMLDivElement>,
  buttonRef: React.RefObject<HTMLButtonElement>,
  column: ColumnInstance,
): 'center' | 'end' | 'start' {
  // Get menu alignment based on column alignment
  let alignment: 'center' | 'end' | 'start';
  if (column.alignment?.endsWith('center')) {
    alignment = 'center';
  } else if (column.alignment?.endsWith('right')) {
    alignment = 'end';
  } else {
    alignment = 'start';
  }

  // Return alignment if refs are undefined or if the table has no scroll bar
  if (
    !buttonRef.current ||
    !tableContainerRef.current ||
    tableContainerRef.current.scrollWidth <=
      tableContainerRef.current.clientWidth
  ) {
    return alignment;
  }

  // Table has a scroll bar, calculate alignment based on location of button
  // in the table
  const buttonRect = buttonRef.current.getBoundingClientRect();
  const tableRect = tableContainerRef.current.getBoundingClientRect();
  if (
    buttonRect.x <= tableRect.x &&
    buttonRect.x + buttonRect.width <= tableRect.x + tableRect.width
  ) {
    // if the left side of the button is overflowing the table whereas the right side is shown inside of it,
    // then align menu at the end
    alignment = 'end';
  } else if (
    buttonRect.x >= tableRect.x &&
    buttonRect.x + buttonRect.width >= tableRect.x + tableRect.width
  ) {
    // if the right side of the button is overflowing the table whereas the left side is shown inside of it,
    // then align menu at the start
    alignment = 'start';
  } else if (
    buttonRect.x < tableRect.x &&
    buttonRect.x + buttonRect.width > tableRect.x + tableRect.width
  ) {
    // if both sides are overflowing the table, align menu at the center of the button
    alignment = 'center';
  }

  return alignment;
}
